    public static void generateKey() throws Exception {
        KeyPair keyPair = KeyManager.generateKeyPair();
        String publicKey = Hex.toHexString(KeyManager.toBytes(keyPair.getPublic()));
        String privateKey = Hex.toHexString(KeyManager.toBytes(keyPair.getPrivate()));
        System.out.println(" 공개키 Public key:"+ publicKey);
        System.out.println(" 비밀키 Private key:"+ privateKey);
    }

    public static void generateCypto(String privateKey) throws Exception {
        // 2. 보안채널 생성
        try {

            PrivateKey clientPrivateKey = KeyManager.loadPrivateKey(Hex.decode(privateKey));
            PublicKey serverPublicKey = KeyManager.loadPublicKey(responsePublicKey);

            CryptoManager cryptoManager = CryptoManager.getInstance();
            byte[] sharedSecret = cryptoManager.getSharedSecretWithECDH(clientPrivateKey, serverPublicKey);
            String cryptoWid = cryptoManager.encryptWithAES(sharedSecret, wid);
            String cryptEncryptPassword = cryptoManager.encryptWithAES(sharedSecret, encryptDevicePassword);
            String cryptPvencstr = cryptoManager.encryptWithAES(sharedSecret, pvencstr);

            System.out.println("cryptoWid:"+cryptoWid);
            System.out.println("cryptEncryptPassword:"+cryptEncryptPassword);
            System.out.println("cryptPvencstr:"+cryptPvencstr);
        }catch (Exception e) {
            e.printStackTrace();
        }
      
    }

    public static void generateBTCWallet(){
        NetworkParameters params = TestNet3Params.get();

        Wallet wallet = Wallet.createDeterministic(
                params,
                Script.ScriptType.P2WPKH   // SegWit 주소 (추천)
        );
        System.out.println("테스트넷 주소: " + wallet.currentReceiveAddress());
        System.out.println("Seed: " + wallet.getKeyChainSeed());
    }

    public static void decodeBase58toHex(){
        byte[] bytes = Base58.decode("dv3qDFk1DTF36Z62bNvrCXe9sKATA6xvVy6A798xxAS");
        String hex = Hex.toHexString(bytes);
        System.out.println("반환 ==>"+hex);
    }
